package com.vault.service;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import javax.crypto.Cipher;import javax.crypto.spec.*;import java.security.*;import java.util.*;
@Service public class CryptoService{private final SecretKeySpec key;public CryptoService(@Value("${app.encryption.secret:}")String secret){if(secret.length()<32)throw new IllegalStateException("ENCRYPTION_SECRET must have at least 32 characters");try{key=new SecretKeySpec(MessageDigest.getInstance("SHA-256").digest(secret.getBytes(java.nio.charset.StandardCharsets.UTF_8)),"AES");}catch(Exception e){throw new IllegalStateException(e);}}public String encrypt(String s){try{byte[] iv=new byte[12];new SecureRandom().nextBytes(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key,new GCMParameterSpec(128,iv));byte[] x=c.doFinal(s.getBytes(java.nio.charset.StandardCharsets.UTF_8)),all=Arrays.copyOf(iv,iv.length+x.length);System.arraycopy(x,0,all,iv.length,x.length);return Base64.getEncoder().encodeToString(all);}catch(Exception e){throw new IllegalStateException(e);}}public String decrypt(String s){try{byte[] all=Base64.getDecoder().decode(s);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key,new GCMParameterSpec(128,Arrays.copyOf(all,12)));return new String(c.doFinal(Arrays.copyOfRange(all,12,all.length)),java.nio.charset.StandardCharsets.UTF_8);}catch(Exception e){throw new IllegalStateException("Decryption failed",e);}}}
